<?php
declare(strict_types=1);
require_once __DIR__.'/game.php';require_once __DIR__.'/discovery.php';
function eqp_streak(array $days): int {$n=0;$d=new DateTimeImmutable('today');if(!in_array($d->format('Y-m-d'),$days,true))$d=$d->modify('-1 day');while(in_array($d->format('Y-m-d'),$days,true)){$n++;$d=$d->modify('-1 day');}return $n;}
function eqp_me(PDO $p,int $uid): array {
 $u=hub_q($p,'SELECT id,email,display_name,created_at FROM eq_users WHERE id=?',[$uid])->fetch();$profile=hub_profile($p,$uid);
 try{$ps=json_decode((string)hub_q($p,'SELECT state FROM eq5_pets WHERE user_id=?',[$uid])->fetchColumn(),true);$pi=$ps['persona']??'';if(preg_match('/^vn-(0[1-9]|1[0-9]|20)$/D',$pi))$profile['persona_image']='/personas/'.$pi.'.webp';}catch(PDOException $e){}
$raw=hub_q($p,'SELECT state FROM eq_progress WHERE user_id=?',[$uid])->fetchColumn();$pr=$raw?json_decode($raw,true,512,JSON_THROW_ON_ERROR):game_initial();$completed=$pr['completed']??[];$speech=(int)hub_q($p,'SELECT COUNT(*) FROM eqx_speaking WHERE user_id=?',[$uid])->fetchColumn();$friends=(int)hub_q($p,"SELECT COUNT(*) FROM eqx_friends f WHERE (f.low_id=? OR f.high_id=?) AND f.status='accepted' AND NOT EXISTS(SELECT 1 FROM eqx_blocks b WHERE (b.user_id=? AND b.target_id=CASE WHEN f.low_id=? THEN f.high_id ELSE f.low_id END) OR (b.target_id=? AND b.user_id=CASE WHEN f.low_id=? THEN f.high_id ELSE f.low_id END))",[$uid,$uid,$uid,$uid,$uid,$uid])->fetchColumn();
 $courses=(int)hub_q($p,"SELECT COUNT(*) FROM eqc_progress WHERE user_id=? AND kind='lesson' AND passed=1",[$uid])->fetchColumn();$streak=eqp_streak($pr['days']??[]);$badges=[];if($courses||count(array_filter($completed,fn($x)=>preg_match('/^(vocabulary|grammar|listening|test)-/',$x))))$badges[]='Bước chân đầu tiên';if($streak>=7)$badges[]='7 ngày bền bỉ';if(count($pr['learned']??[])>=30)$badges[]='Kho từ vựng nhỏ';foreach([1=>'Cất tiếng đầu tiên',10=>'10 lượt luyện nói',50=>'50 lượt luyện nói'] as $n=>$label)if($speech>=$n)$badges[]=$label;
 $ranks=[[0,'Trứng'],[100,'Đồng'],[400,'Bạc'],[900,'Vàng'],[1600,'Kim cương'],[2400,'Master']];$rank='Trứng';$level=1;foreach($ranks as $i=>$r)if(($pr['xp']??0)>=$r[0]){$rank=$r[1];$level=$i+1;}
 return ['user'=>public_user($u),'joined_at'=>$u['created_at'],'profile'=>$profile,'stats'=>['xp'=>(int)($pr['xp']??0),'rank'=>$rank,'rank_level'=>$level,'streak'=>$streak,'speaking'=>$speech,'friends'=>$friends,'courses'=>$courses,'lessons'=>$courses+count(array_filter($completed,fn($x)=>preg_match('/^(vocabulary|grammar|listening|test)-/',$x))),'badges'=>$badges,'skills'=>['Từ đã nhớ'=>count($pr['learned']??[]),'Ngữ pháp'=>count(array_filter($completed,fn($x)=>str_starts_with($x,'grammar-'))),'Luyện nghe'=>count(array_filter($completed,fn($x)=>str_starts_with($x,'listening-'))),'Luyện nói'=>$speech,'Bài giáo trình'=>$courses]],'history'=>$pr['history']??[],'pending_email'=>hub_q($p,'SELECT email,created_at FROM eqp_email_changes WHERE user_id=?',[$uid])->fetch()?:null];
}
function eqp_email_begin(PDO $p,array $config,array $u,array $in): never {
 $uid=(int)$u['id'];$email=email_value(field($in,'email'));if($email===$u['email'])fail(422,'Email mới trùng email hiện tại.');if(!password_verify(field($in,'current_password'),$u['password_hash']))fail(422,'Mật khẩu hiện tại chưa đúng.');if(!eq_mail_ready($config))eq_auth_error(503,'SMTP_NOT_READY','Cần cấu hình SMTP trước khi gửi xác minh email mới. Email hiện tại vẫn được giữ nguyên.');
 limit_attempts($p,'email-change:'.$uid,3,3600);limit_attempts($p,'email-change-to:'.$email,5,3600);if(hub_q($p,'SELECT 1 FROM eq_users WHERE email=?',[$email])->fetchColumn())fail(409,'Email này đang được sử dụng.');$token=bin2hex(random_bytes(32));$now=time();$p->beginTransaction();try{
  $locked=hub_q($p,'SELECT * FROM eq_users WHERE id=?'.($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$uid])->fetch();if((int)$locked['auth_version']!==(int)$u['auth_version']){$p->rollBack();fail(409,'Thông tin bảo mật đã thay đổi. Hãy đăng nhập lại.');}
  hub_q($p,"UPDATE eq_auth_tokens SET expires_at=? WHERE user_id=? AND purpose='email_change' AND used_at IS NULL",[$now,$uid]);hub_q($p,'DELETE FROM eqp_email_changes WHERE user_id=?',[$uid]);hub_q($p,'INSERT INTO eqp_email_changes(user_id,email,old_email,auth_version,created_at) VALUES (?,?,?,?,?)',[$uid,$email,$u['email'],$u['auth_version'],$now]);hub_q($p,'INSERT INTO eq_auth_tokens(token_hash,user_id,email,purpose,expires_at,created_at) VALUES (?,?,?,?,?,?)',[hash('sha256',$token),$uid,$email,'email_change',$now+3600,$now]);$p->commit();
 }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
 try{eq_send_email($config,$email,$token,'email_change');eq_auth_log($p,'email_change_sent',$uid,$email);}catch(Throwable $e){hub_q($p,'UPDATE eq_auth_tokens SET expires_at=? WHERE token_hash=?',[time(),hash('sha256',$token)]);fail(503,'Chưa gửi được thư xác minh. Email hiện tại vẫn hoạt động.');}
 reply(200,['ok'=>true,'pending_email'=>$email,'message'=>'Đã gửi xác minh đến email mới. Email đăng nhập chỉ đổi sau khi bạn xác nhận liên kết.']);
}
function eqp_email_confirm(PDO $p,array $in): never {
 $token=field($in,'token');if(!preg_match('/^[a-f0-9]{64}$/D',$token))fail(422,'Liên kết đổi email không hợp lệ hoặc đã hết hạn.');$hash=hash('sha256',$token);$peek=hub_q($p,"SELECT user_id FROM eq_auth_tokens WHERE token_hash=? AND purpose='email_change'",[$hash])->fetchColumn();if(!$peek)fail(422,'Liên kết đổi email không hợp lệ hoặc đã hết hạn.');
 $p->beginTransaction();try{
  $lock=$p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$u=hub_q($p,'SELECT * FROM eq_users WHERE id=?'.$lock,[$peek])->fetch();$t=hub_q($p,"SELECT * FROM eq_auth_tokens WHERE token_hash=? AND purpose='email_change'".$lock,[$hash])->fetch();$pending=hub_q($p,'SELECT * FROM eqp_email_changes WHERE user_id=?'.$lock,[$peek])->fetch();
  if(!$u||!$t||!$pending||$t['used_at']!==null||(int)$t['expires_at']<=time()||$u['email']!==$pending['old_email']||(int)$u['auth_version']!==(int)$pending['auth_version']||$t['email']!==$pending['email']){$p->rollBack();fail(422,'Liên kết đã hết hạn, đã dùng hoặc thông tin bảo mật đã thay đổi.');}
  hub_q($p,'UPDATE eq_users SET email=?,auth_version=auth_version+1 WHERE id=?',[$t['email'],$peek]);hub_q($p,"UPDATE eq_auth_accounts SET status='active',verified_email=?,email_verified_at=?,legacy_access=0 WHERE user_id=?",[$t['email'],time(),$peek]);hub_q($p,'UPDATE eqx_profiles SET verified_email=? WHERE user_id=?',[$t['email'],$peek]);hub_q($p,'UPDATE eq_auth_tokens SET used_at=? WHERE user_id=? AND used_at IS NULL',[time(),$peek]);hub_q($p,'UPDATE eq_password_resets SET expires_at=? WHERE user_id=?',[time(),$peek]);hub_q($p,'UPDATE eqx_sessions SET revoked=1 WHERE user_id=?',[$peek]);hub_q($p,'DELETE FROM eqp_email_changes WHERE user_id=?',[$peek]);eq_auth_log($p,'email_changed',(int)$peek,$t['email']);$p->commit();
 }catch(PDOException $e){if($p->inTransaction())$p->rollBack();if((string)$e->getCode()==='23000')fail(409,'Email mới đã được một tài khoản khác sử dụng. Email cũ của bạn vẫn được giữ nguyên.');throw $e;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
 $_SESSION=[];session_regenerate_id(true);reply(200,['ok'=>true,'user'=>null,'csrf'=>csrf(),'email'=>$t['email'],'message'=>'Email mới đã được xác minh. Hãy đăng nhập lại bằng địa chỉ mới.']);
}
function eq_profile(PDO $p,int $uid,array $config,string $op,array $in): never {
 if($op==='profile_me')reply(200,['ok'=>true]+eqp_me($p,$uid));
 if($op==='profile_email_begin'){$u=hub_q($p,'SELECT * FROM eq_users WHERE id=?',[$uid])->fetch();eqp_email_begin($p,$config,$u,$in);}
 if($op==='profile_email_cancel'){hub_q($p,'DELETE FROM eqp_email_changes WHERE user_id=?',[$uid]);hub_q($p,"UPDATE eq_auth_tokens SET expires_at=? WHERE user_id=? AND purpose='email_change' AND used_at IS NULL",[time(),$uid]);reply(200,['ok'=>true,'message'=>'Đã hủy yêu cầu đổi email.']);}
 if($op==='profile_password_change'){
  limit_attempts($p,'password-change:'.$uid,8,900);$new=password_value(field($in,'password'));if(!hash_equals($new,field($in,'password_confirmation')))fail(422,'Mật khẩu nhập lại chưa khớp.');$p->beginTransaction();try{
   $u=hub_q($p,'SELECT * FROM eq_users WHERE id=?'.($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$uid])->fetch();if(!password_verify(field($in,'current_password'),$u['password_hash'])){$p->rollBack();fail(422,'Mật khẩu hiện tại chưa đúng.');}hub_q($p,'UPDATE eq_users SET password_hash=?,auth_version=auth_version+1 WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$uid]);hub_q($p,'UPDATE eqx_sessions SET revoked=1 WHERE user_id=?',[$uid]);hub_q($p,'UPDATE eq_auth_tokens SET expires_at=? WHERE user_id=? AND used_at IS NULL',[time(),$uid]);hub_q($p,'DELETE FROM eqp_email_changes WHERE user_id=?',[$uid]);hub_q($p,'UPDATE eq_password_resets SET expires_at=? WHERE user_id=?',[time(),$uid]);eq_auth_log($p,'password_changed',$uid);$p->commit();
  }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}$_SESSION=[];session_regenerate_id(true);reply(200,['ok'=>true,'user'=>null,'csrf'=>csrf(),'reauthenticate'=>true,'message'=>'Đã đổi mật khẩu và thu hồi các phiên. Hãy đăng nhập lại.']);
 }
 if($op==='profile_revoke_others'){hub_q($p,'UPDATE eqx_sessions SET revoked=1 WHERE user_id=? AND token<>?',[$uid,hash('sha256',session_id())]);reply(200,['ok'=>true,'message'=>'Đã đăng xuất các thiết bị khác.']);}
 fail(404,'Không tìm thấy chức năng hồ sơ.');
}
